// Kiro's balance reflex: step into a push.
// A slow low-pass of the pelvis velocity is the walking baseline. A velocity change beyond a dead band
// (in m/s) is read as a shove, and the command is shifted in that direction so the policy steps after it.
import { Reflex } from './reflex.js';
import type { ReflexState } from './reflex.js';

const ALPHA = 0.02;      // baseline low-pass gain per 20 ms Control_Step
const DEAD = 0.25;       // dead band, m/s
const GAIN = 1.0;        // command shift per m/s of excess velocity
const CAP = 0.6;         // max command shift, m/s

export class KiroReflex extends Reflex {
  private bx = 0;
  private by = 0;
  private init = false;

  override reset(): void { this.bx = 0; this.by = 0; this.init = false; }

  override command(s: ReflexState, base: ArrayLike<number>, out: Float64Array): void {
    out[0] = base[0] as number;
    out[1] = base[1] as number;
    out[2] = base[2] as number;
    const wx = s.qvel[0] as number, wy = s.qvel[1] as number;
    if (!this.init) { this.bx = wx; this.by = wy; this.init = true; }
    const dx = wx - this.bx, dy = wy - this.by;
    this.bx += ALPHA * dx;
    this.by += ALPHA * dy;
    // Rotate the world-frame velocity change into the heading frame.
    const qw = s.qpos[3] as number, qx = s.qpos[4] as number, qy = s.qpos[5] as number, qz = s.qpos[6] as number;
    const yaw = Math.atan2(2 * (qw * qz + qx * qy), 1 - 2 * (qy * qy + qz * qz));
    const c = Math.cos(yaw), si = Math.sin(yaw);
    const fx = c * dx + si * dy;
    const fy = -si * dx + c * dy;
    out[0] = (base[0] as number) + shift(fx);
    out[1] = (base[1] as number) + shift(fy);
  }
}

function shift(d: number): number {
  const m = Math.abs(d) - DEAD;
  if (m <= 0) return 0;
  return Math.sign(d) * Math.min(CAP, GAIN * m);
}

